$(document).ready(function(){$.ajax({url:"/api/simrs/userpas",method:"GET",success:function(s){console.log(s),$("#simrs_User").val(s.data.user),$("#simrs_Password").val(s.data.password)},error:function(s){console.error(s.responseJSON),$("#simrs_accoun").html("<strong>"+s.responseJSON.message+"</strong> <br> <small>Silahkan Hubungi IT</small>")}})});
